:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #24352f;
  background: #f2efe8;
  font-synthesis: none;
}

* { box-sizing: border-box; }
body { min-width: 360px; min-height: 100vh; margin: 0; padding: 36px 20px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #e5ede4 0, #f2efe8 65%); }
.card { width: min(100%, 490px); padding: 36px; border: 1px solid #e1e5dc; border-radius: 24px; background: #fffefa; box-shadow: 0 18px 55px #263d3212; }
.header { text-align: center; }
.icon { width: 52px; height: 52px; margin: 0 auto 18px; display: grid; place-items: center; border-radius: 17px; background: #dce9dc; color: #2b604b; font-size: 30px; font-weight: 750; }
.eyebrow { margin: 0 0 6px; color: #59806b; font-size: .82rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
h1 { margin: 0; color: #203c30; font-size: clamp(2rem, 8vw, 2.6rem); letter-spacing: -.055em; }
.intro { max-width: 350px; margin: 12px auto 28px; color: #65736a; line-height: 1.55; }
.fields { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.field label { display: block; margin-bottom: 8px; font-weight: 650; }
.input-wrap { display: flex; align-items: center; gap: 8px; padding: 0 13px; border: 1px solid #d6ddd5; border-radius: 12px; background: #fff; color: #718077; }
.input-wrap:focus-within { border-color: #398061; box-shadow: 0 0 0 3px #39806125; }
input { width: 100%; min-width: 0; height: 50px; border: 0; outline: 0; background: transparent; color: #24352f; font: inherit; font-size: 1.1rem; }
input::placeholder { color: #a3ada5; }
button { width: 100%; min-height: 52px; margin-top: 20px; padding: 12px 18px; display: flex; align-items: center; justify-content: center; gap: 10px; border: 0; border-radius: 12px; background: #2f7054; color: white; font: inherit; font-weight: 700; cursor: pointer; transition: background .15s, transform .15s, box-shadow .15s; }
button:hover { background: #245c43; box-shadow: 0 5px 14px #245c4330; }
button:focus-visible { outline: 3px solid #7ca98e; outline-offset: 3px; }
button:active { transform: translateY(1px); background: #1e4f39; }
.message { min-height: 24px; margin: 14px 0 0; color: #65736a; text-align: center; font-size: .92rem; }
.message.error { color: #a34135; }
.results { margin-top: 22px; padding: 20px; border-radius: 16px; background: #f4f7f1; }
.change-total { display: flex; align-items: center; justify-content: space-between; padding-bottom: 18px; border-bottom: 1px solid #dfe7dd; color: #52645a; }
.change-total strong { color: #244a36; font-size: 1.8rem; letter-spacing: -.04em; }
.breakdown-heading { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin: 18px 0 10px; }
h2 { margin: 0; font-size: 1rem; }
#piece-count { color: #65736a; font-size: .86rem; }
.denominations { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin: 0; padding: 0; list-style: none; }
.denomination { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px 12px; border: 1px solid #e2e9df; border-radius: 10px; background: #fffefa; }
.denomination span { color: #52645a; }
.denomination strong { color: #244a36; }
.note { margin: 12px 0 0; color: #8a5b28; font-size: .88rem; line-height: 1.45; }
footer { margin-top: 22px; color: #839087; text-align: center; font-size: .78rem; line-height: 1.5; }
[hidden] { display: none !important; }
@media (max-width: 430px) { body { padding: 20px 12px; } .card { padding: 27px 20px; border-radius: 20px; } .fields { gap: 10px; } .input-wrap { padding: 0 10px; } }

const denominations = [
  { cents: 2000, label: '$20' },
  { cents: 1000, label: '$10' },
  { cents: 500, label: '$5' },
  { cents: 200, label: '$2' },
  { cents: 100, label: '$1' },
  { cents: 50, label: '50¢' },
  { cents: 20, label: '20¢' },
  { cents: 10, label: '10¢' },
  { cents: 5, label: '5¢' }
];

const form = document.querySelector('#change-form');
const priceInput = document.querySelector('#price');
const paidInput = document.querySelector('#paid');
const message = document.querySelector('#message');
const results = document.querySelector('#results');
const changeAmount = document.querySelector('#change-amount');
const pieceCount = document.querySelector('#piece-count');
const list = document.querySelector('#denominations');
const unrepresented = document.querySelector('#unrepresented');

function toCents(value) {
  const amount = Number(value);
  if (!Number.isFinite(amount) || amount < 0) return null;
  return Math.round((amount + Number.EPSILON) * 100);
}

function formatMoney(cents) {
  return `$${(cents / 100).toFixed(2)}`;
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const price = toCents(priceInput.value);
  const paid = toCents(paidInput.value);

  if (price === null || paid === null) {
    results.hidden = true;
    message.textContent = 'Enter valid, non-negative amounts in both fields.';
    message.classList.add('error');
    (price === null ? priceInput : paidInput).focus();
    return;
  }
  if (paid < price) {
    results.hidden = true;
    message.textContent = 'The amount paid must be at least the price.';
    message.classList.add('error');
    paidInput.focus();
    return;
  }

  message.textContent = 'Change calculated.';
  message.classList.remove('error');
  results.hidden = false;
  const change = paid - price;
  changeAmount.textContent = formatMoney(change);

  let remainder = change;
  let total = 0;
  list.replaceChildren();
  for (const denomination of denominations) {
    const count = Math.floor(remainder / denomination.cents);
    remainder %= denomination.cents;
    if (count === 0) continue;
    total += count;
    const item = document.createElement('li');
    item.className = 'denomination';
    const label = document.createElement('span');
    label.textContent = denomination.label;
    const quantity = document.createElement('strong');
    quantity.textContent = `× ${count}`;
    item.append(label, quantity);
    list.append(item);
  }
  pieceCount.textContent = `${total} ${total === 1 ? 'piece' : 'pieces'}`;
  unrepresented.hidden = remainder === 0;
  if (remainder > 0) {
    unrepresented.textContent = `${formatMoney(remainder)} cannot be represented with the available denominations.`;
  }
});
